 24→	"github.com/go-git/go-git/v6/plumbing/object"
 25→)
 26→
 27→// WriteCommitted writes a committed checkpoint to both v2 refs:
 28→//   - /main: metadata and prompts (no raw transcript or content hash)
 29→//   - /full/current: raw transcript + content hash (replaces previous content)
 30→//
 31→// This is the public entry point for v2 dual-writes. The session index is
 32→// determined from the /main ref and passed to the /full/current write to
 33→// keep both refs consistent.
 34→func (s *V2GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
 35→	// Validate upfront before any writes to avoid partial ref updates
 36→	if err := validateWriteOpts(opts); err != nil {
 37→		return err
 38→	}
 39→
 40→	sessionIndex, err := s.writeCommittedMain(ctx, opts)
 41→	if err != nil {
 42→		return fmt.Errorf("v2 /main write failed: %w", err)
 43→	}
 44→
 45→	if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 46→		return fmt.Errorf("v2 /full/current write failed: %w", err)
 47→	}
 48→
 49→	return nil
 50→}
 51→
 52→// UpdateCommitted replaces the prompts and/or transcript for an existing v2 checkpoint.
 53→// Called at stop time to finalize checkpoints with the complete session transcript.
 54→//
 55→// On /main: replaces prompts and compact transcript (if provided).
 56→// On /full/current: replaces the raw transcript (if provided).
 57→//
 58→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
 59→func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
 60→	if opts.CheckpointID.IsEmpty() {
 61→		return errors.New("invalid update options: checkpoint ID is required")
 62→	}
 63→
 64→	sessionIndex, err := s.updateCommittedMain(ctx, opts)
 65→	if err != nil {
 66→		return fmt.Errorf("v2 /main update failed: %w", err)
 67→	}
 68→
 69→	if len(opts.Transcript) > 0 {
 70→		if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
 71→			return fmt.Errorf("v2 /full/current update failed: %w", err)
 72→		}
 73→	}
 74→
 75→	return nil
 76→}
 77→
 78→// updateCommittedMain updates prompts and compact transcript on the /main ref for an existing checkpoint.
 79→// Returns the session index for coordination with /full/current.
 80→func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
 81→	refName := plumbing.ReferenceName(paths.V2MainRefName)
 82→	parentHash, rootTreeHash, err := s.GetRefState(refName)
 83→	if err != nil {
 84→		return 0, ErrCheckpointNotFound
 85→	}
 86→
 87→	basePath := opts.CheckpointID.Path() + "/"
 88→	checkpointPath := opts.CheckpointID.Path()
 89→
 90→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
 91→	if err != nil {
 92→		return 0, err
 93→	}
 94→
 95→	rootMetadataPath := basePath + paths.MetadataFileName
 96→	entry, exists := entries[rootMetadataPath]
 97→	if !exists {
 98→		return 0, ErrCheckpointNotFound
 99→	}
100→
101→	summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
102→	if err != nil {
103→		return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
104→	}
105→	if len(summary.Sessions) == 0 {
106→		return 0, ErrCheckpointNotFound
107→	}
108→
109→	// Find session index by ID, fall back to latest
110→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
111→	if sessionIndex >= len(summary.Sessions) {
112→		// findSessionIndex returns next-available when not found; fall back to latest
113→		sessionIndex = len(summary.Sessions) - 1
114→		logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
115→			slog.String("session_id", opts.SessionID),
116→			slog.String("checkpoint_id", string(opts.CheckpointID)),
117→			slog.Int("fallback_index", sessionIndex),
118→		)
119→	}
120→
121→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
122→
123→	if len(opts.Prompts) > 0 {
124→		promptContent := redact.String(JoinPrompts(opts.Prompts))
125→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
126→		if err != nil {
127→			return 0, fmt.Errorf("failed to create prompt blob: %w", err)
128→		}
129→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
130→			Name: sessionPath + paths.PromptFileName,
131→			Mode: filemode.Regular,
132→			Hash: blobHash,
133→		}
134→	}
135→
136→	// Replace compact transcript if provided
137→	if len(opts.CompactTranscript) > 0 {
138→		blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
139→		if err != nil {
140→			return 0, fmt.Errorf("failed to create compact transcript blob: %w", err)
141→		}
142→		entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
143→			Name: sessionPath + paths.CompactTranscriptFileName,
144→			Mode: filemode.Regular,
145→			Hash: blobHash,
146→		}
147→
148→		if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
149→			return 0, fmt.Errorf("failed to write compact transcript hash: %w", err)
150→		}
151→
152→		// Keep root checkpoint summary in sync with compact artifact paths.
153→		if sessionIndex >= 0 && sessionIndex < len(summary.Sessions) {
154→			summary.Sessions[sessionIndex].Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
155→			summary.Sessions[sessionIndex].ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
156→
157→			summaryBytes, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
158→			if err != nil {
159→				return 0, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
160→			}
161→			summaryHash, err := CreateBlobFromContent(s.repo, summaryBytes)
162→			if err != nil {
163→				return 0, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
164→			}
165→			entries[rootMetadataPath] = object.TreeEntry{
166→				Name: rootMetadataPath,
167→				Mode: filemode.Regular,
168→				Hash: summaryHash,
169→			}
170→		}
171→	}
172→
173→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
174→	if err != nil {
175→		return 0, err
176→	}
177→
178→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
179→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
180→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
181→		return 0, err
182→	}
183→
184→	return sessionIndex, nil
185→}
186→
187→// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
188→// on /full/current while preserving other checkpoints' transcripts in the tree.
189→func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
190→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
191→	if err := s.ensureRef(refName); err != nil {
192→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
193→	}
194→
195→	parentHash, rootTreeHash, err := s.GetRefState(refName)
196→	if err != nil {
197→		return err
198→	}
199→
200→	basePath := opts.CheckpointID.Path() + "/"
201→	checkpointPath := opts.CheckpointID.Path()
202→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
203→
204→	// Read existing entries and replace transcript for this checkpoint only
205→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
206→	if err != nil {
207→		return err
208→	}
209→
210→	// Clear existing transcript entries at this session path before writing new ones
211→	for key := range entries {
212→		if strings.HasPrefix(key, sessionPath) {
213→			delete(entries, key)
214→		}
215→	}
216→
217→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, sessionPath, entries)
218→	if err != nil {
219→		return err
220→	}
221→
222→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
223→		return err
224→	}
225→
226→	// Splice into existing root tree (preserves other checkpoints' transcripts)
227→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
228→	if err != nil {
229→		return err
230→	}
231→
232→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
233→	commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
234→	return s.updateRef(refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
235→}
236→
237→// writeCommittedMain writes metadata entries to the /main ref.
238→// This includes session metadata and prompts — but NOT the raw transcript
239→// (full.jsonl) or content hash (content_hash.txt), which go to /full/current.
240→// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
241→func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
242→	refName := plumbing.ReferenceName(paths.V2MainRefName)
243→	if err := s.ensureRef(refName); err != nil {
244→		return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
245→	}
246→
247→	parentHash, rootTreeHash, err := s.GetRefState(refName)
248→	if err != nil {
249→		return 0, err
250→	}
251→
252→	basePath := opts.CheckpointID.Path() + "/"
253→	checkpointPath := opts.CheckpointID.Path()
254→
255→	// Read existing entries at this checkpoint's shard path
256→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
257→	if err != nil {
258→		return 0, err
259→	}
260→
261→	// Build main session entries (metadata, prompts — no transcript or content hash)
262→	sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
263→	if err != nil {
264→		return 0, err
265→	}
266→
267→	// Splice entries into root tree
268→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
269→	if err != nil {
270→		return 0, err
271→	}
272→
273→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
274→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
275→		return 0, err
276→	}
277→	return sessionIndex, nil
278→}
279→
280→// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
281→// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
282→// Returns the session index used, for coordination with writeCommittedFullTranscript.
283→func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
284→	// Read existing summary to get current session count
285→	var existingSummary *CheckpointSummary
286→	metadataPath := basePath + paths.MetadataFileName
287→	if entry, exists := entries[metadataPath]; exists {
288→		existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
289→		if err == nil {
290→			existingSummary = existing
291→		}
292→	}
293→
294→	// Determine session index
295→	sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
296→
297→	// Write session files (metadata and prompts — no transcript or content hash)
298→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
299→	sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
300→	if err != nil {
301→		return 0, err
302→	}
303→
304→	// Build the sessions array
305→	var sessions []SessionFilePaths
306→	if existingSummary != nil {
307→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
308→		copy(sessions, existingSummary.Sessions)
309→	} else {
310→		sessions = make([]SessionFilePaths, 1)
311→	}
312→	sessions[sessionIndex] = sessionFilePaths
313→
314→	// Write root CheckpointSummary
315→	if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
316→		return 0, err
317→	}
318→	return sessionIndex, nil
319→}
320→
321→// writeMainSessionToSubdirectory writes a single session's metadata, prompts,
322→// and compact transcript to a session subdirectory (0/, 1/, 2/, … indexed by
323→// session order within the checkpoint). The raw transcript (full.jsonl) and its
324→// content hash (content_hash.txt) go to /full/current, not here.
325→func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
326→	filePaths := SessionFilePaths{}
327→
328→	// Clear existing entries at this session path
329→	for key := range entries {
330→		if strings.HasPrefix(key, sessionPath) {
331→			delete(entries, key)
332→		}
333→	}
334→
335→	// Write prompts
336→	if len(opts.Prompts) > 0 {
337→		promptContent := redact.String(JoinPrompts(opts.Prompts))
338→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
339→		if err != nil {
340→			return filePaths, err
341→		}
342→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
343→			Name: sessionPath + paths.PromptFileName,
344→			Mode: filemode.Regular,
345→			Hash: blobHash,
346→		}
347→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
348→	}
349→
350→	// Write compact transcript (transcript.jsonl) + hash if provided
351→	if len(opts.CompactTranscript) > 0 {
352→		blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
353→		if err != nil {
354→			return filePaths, fmt.Errorf("failed to create compact transcript blob: %w", err)
355→		}
356→		entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
357→			Name: sessionPath + paths.CompactTranscriptFileName,
358→			Mode: filemode.Regular,
359→			Hash: blobHash,
360→		}
361→		filePaths.Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
362→
363→		if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
364→			return filePaths, fmt.Errorf("failed to write compact transcript hash: %w", err)
365→		}
366→		filePaths.ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
367→	}
368→
369→	// Write session metadata
370→	sessionMetadata := CommittedMetadata{
371→		CheckpointID:                opts.CheckpointID,
372→		SessionID:                   opts.SessionID,
373→		Strategy:                    opts.Strategy,
374→		CreatedAt:                   time.Now().UTC(),
375→		Branch:                      opts.Branch,
376→		CheckpointsCount:            opts.CheckpointsCount,
377→		FilesTouched:                opts.FilesTouched,
378→		Agent:                       opts.Agent,
379→		Model:                       opts.Model,
380→		TurnID:                      opts.TurnID,
381→		IsTask:                      opts.IsTask,
382→		ToolUseID:                   opts.ToolUseID,
383→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
384→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
385→		TokenUsage:                  opts.TokenUsage,
386→		SessionMetrics:              opts.SessionMetrics,
387→		InitialAttribution:          opts.InitialAttribution,
388→		PromptAttributions:          opts.PromptAttributionsJSON,
389→		Summary:                     redactSummary(opts.Summary),
390→		CLIVersion:                  versioninfo.Version,
391→	}
392→
393→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
394→	if err != nil {
395→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
396→	}
397→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
398→	if err != nil {
399→		return filePaths, err
400→	}
401→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
402→		Name: sessionPath + paths.MetadataFileName,
403→		Mode: filemode.Regular,
404→		Hash: metadataHash,
405→	}
406→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
407→
408→	return filePaths, nil
409→}
410→
411→// writeContentHash computes and writes the content hash for already-redacted transcript bytes.
412→func (s *V2GitStore) writeContentHash(redactedTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
413→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(redactedTranscript))
414→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
415→	if err != nil {
416→		return err
417→	}
418→	entries[sessionPath+paths.ContentHashFileName] = object.TreeEntry{
419→		Name: sessionPath + paths.ContentHashFileName,
420→		Mode: filemode.Regular,
421→		Hash: hashBlob,
422→	}
423→	return nil
424→}
425→
426→// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
427→func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
428→	hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
429→	blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
430→	if err != nil {
431→		return err
432→	}
433→	entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
434→		Name: sessionPath + paths.CompactTranscriptHashFileName,
435→		Mode: filemode.Regular,
436→		Hash: blobHash,
437→	}
438→	return nil
439→}
440→
441→// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
442→// Transcripts accumulate across checkpoints — each write splices into the existing
443→// tree. Generation metadata (generation.json) at the tree root is updated on every
444→// write with the new checkpoint ID and timestamps.
445→//
446→// sessionIndex is the session slot (0-based), determined by the caller to stay
447→// consistent with the /main ref's session numbering.
448→// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
449→func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
450→	transcript := opts.Transcript
451→	if len(transcript) == 0 && opts.TranscriptPath != "" {
452→		var readErr error
453→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
454→		if readErr != nil {
455→			transcript = nil
456→		}
457→	}
458→	if len(transcript) == 0 {
459→		return nil // No transcript to write
460→	}
461→
462→	refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
463→	if err := s.ensureRef(refName); err != nil {
464→		return fmt.Errorf("failed to ensure /full/current ref: %w", err)
465→	}
466→
467→	parentHash, rootTreeHash, err := s.GetRefState(refName)
468→	if err != nil {
469→		return err
470→	}
471→
472→	basePath := opts.CheckpointID.Path() + "/"
473→	checkpointPath := opts.CheckpointID.Path()
474→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
475→
476→	// Read existing entries at this checkpoint's shard path
477→	entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
478→	if err != nil {
479→		return err
480→	}
481→
482→	// Clear existing entries at this session path before writing new ones
483→	for key := range entries {
484→		if strings.HasPrefix(key, sessionPath) {
485→			delete(entries, key)
486→		}
487→	}
488→
489→	redactedTranscript, err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, sessionPath, entries)
490→	if err != nil {
491→		return err
492→	}
493→
494→	if err := s.writeContentHash(redactedTranscript, sessionPath, entries); err != nil {
495→		return err
496→	}
497→
498→	// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
499→	newTreeHash, err := s.gs.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
500→	if err != nil {
501→		return err
502→	}
503→
504→	commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
505→	if err := s.updateRef(refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
506→		return err
507→	}
508→
509→	// Check if rotation is needed after successful write.
510→	// Count checkpoints by walking the tree (no generation.json on /full/current).
511→	checkpointCount, countErr := s.CountCheckpointsInTree(newTreeHash)
512→	if countErr != nil {
513→		logging.Warn(ctx, "failed to count checkpoints for rotation check",
514→			slog.String("error", countErr.Error()),
515→		)
516→		return nil
517→	}
518→	if checkpointCount >= s.maxCheckpoints() {
519→		if rotErr := s.rotateGeneration(ctx); rotErr != nil {
520→			logging.Warn(ctx, "generation rotation failed",
521→				slog.String("error", rotErr.Error()),
522→				slog.Int("checkpoint_count", checkpointCount),
523→			)
524→			// Non-fatal: rotation failure doesn't invalidate the write
525→		}
526→	}
527→
528→	return nil
529→}
530→
531→// writeTranscriptBlobs writes redacted, chunked transcript blobs to entries.
532→// Returns the redacted transcript bytes so the caller can compute the content hash.
533→func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) ([]byte, error) {
534→	// Redact secrets before chunking
535→	redacted, err := redact.JSONLBytes(transcript)
536→	if err != nil {
537→		return nil, fmt.Errorf("failed to redact transcript: %w", err)
538→	}
539→
540→	chunks, err := agent.ChunkTranscript(ctx, redacted, agentType)
541→	if err != nil {
542→		return nil, fmt.Errorf("failed to chunk transcript: %w", err)
543→	}
544→
545→	for i, chunk := range chunks {
546→		chunkPath := sessionPath + agent.ChunkFileName(paths.TranscriptFileName, i)
547→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
548→		if err != nil {
549→			return nil, err
550→		}
551→		entries[chunkPath] = object.TreeEntry{
552→			Name: chunkPath,
553→			Mode: filemode.Regular,
554→			Hash: blobHash,
555→		}
556→	}
557→
558→	return redacted, nil
559→}
560→
561→// validateWriteOpts validates identifiers in WriteCommittedOptions.
562→func validateWriteOpts(opts WriteCommittedOptions) error {
563→	if opts.CheckpointID.IsEmpty() {
564→		return errors.New("invalid checkpoint options: checkpoint ID is required")
565→	}
566→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
567→		return fmt.Errorf("invalid checkpoint options: %w", err)
568→	}
569→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
570→		return fmt.Errorf("invalid checkpoint options: %w", err)
571→	}
572→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
573→		return fmt.Errorf("invalid checkpoint options: %w", err)
574→	}
575→	return nil
576→}
